class Solution:
    def decrypt(self, code: list[int], k: int) -> list[int]:
        n = len(code)
        ans = [0] * n

        if k == 0:
            return ans

        if k > 0:
            start, end = 1, k
        else:
            start, end = n + k, n - 1

        curSum = 0
        for i in range(start, end + 1):
            curSum += code[i % n]

        for i in range(n):
            ans[i] = curSum

            curSum -= code[start % n]
            start += 1
            end += 1
            curSum += code[end % n]

        return ans
